create extension if not exists pgcrypto;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null default 'scholar' check(role in('admin','staff','scholar')),created_at timestamptz default now());
create table scholarship_programs(id uuid primary key default gen_random_uuid(),program_name text not null unique,required_gwa numeric not null check(required_gwa between 1 and 5),min_units integer not null check(min_units>=0),allow_failing_grade boolean default false,active boolean default true,created_at timestamptz default now());
create table scholars(id uuid primary key default gen_random_uuid(),student_id text not null unique check(length(trim(student_id))>0),full_name text not null,degree_program text not null,year_level integer not null check(year_level between 1 and 6),scholarship_id uuid not null references scholarship_programs(id),user_id uuid references auth.users(id),status text not null default 'Pending Submission' check(status in('Active','Pending Submission','For Verification','Compliant','With Deficiency','Probationary','For Renewal','Renewed','Disqualified')),created_at timestamptz default now());
create table grade_submissions(id uuid primary key default gen_random_uuid(),scholar_id uuid not null references scholars(id) on delete cascade,academic_year text not null,semester text not null,gwa numeric not null check(gwa between 1 and 5),units_enrolled integer not null check(units_enrolled>=0),failed_subjects integer default 0 check(failed_subjects>=0),incomplete_subjects integer default 0 check(incomplete_subjects>=0),submission_status text not null default 'Pending' check(submission_status in('Pending','Verified','Returned')),submitted_at timestamptz default now(),verified_by uuid references auth.users(id),verified_at timestamptz,compliance_result text check(compliance_result in('Compliant','With Deficiency')),deficiency_reason text);
create index on scholars(scholarship_id);create index on scholars(status);create index on grade_submissions(scholar_id);create index on grade_submissions(submission_status);
create or replace function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','New User'),'scholar');
update scholars set user_id=new.id where student_id=new.raw_user_meta_data->>'student_id' and user_id is null; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();
